if (MeType == 0x10 || MeHealth < 10) {
        MeEggCarried = 0xfd;
        egg = FindEggAt(&index, plane, x, y);
        if (egg >= 0) {
            SetAntIndex(plane, index, 0, 0, 0, 0, 0);
            if (x != MeLocX || y != MeLocY)
                SetLife(plane, x, y, 0);
            if (MeHealth >= 10) {
                myBeginSound(0x1c, 0, 0x7e);
                MeEggCarried = egg;
                MeType = 8;
            } else
                MeFoodInType = 3;
            return 1;
        }
    }
    return 0;

